import React, { useState, useEffect } from "react";
import axios from "axios";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminManageHome() {
  const [homeData, setHomeData] = useState({
    bannerVideos: [],
    welcomeText: "",
    activityImages: [],
    threeColSection: [
      { title: "Latest News", content: "", image: "" },
      { title: "Activity Calendar", content: "", image: "" },
      { title: "GIPS Video", content: "", image: "" },
    ],
    testimonialVideos: [],
  });

  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => {
        setHomeData(res.data || homeData);
        setLoading(false);
      })
      .catch(() => {
        toast.error("Failed to load home page data");
        setLoading(false);
      });
  }, []);

  const handleVideoChange = (e, index) => {
    const newVideos = [...homeData.bannerVideos];
    newVideos[index] = e.target.value;
    setHomeData({ ...homeData, bannerVideos: newVideos });
  };

  const handleActivityImageChange = (e, index) => {
    const newImages = [...homeData.activityImages];
    newImages[index] = e.target.value;
    setHomeData({ ...homeData, activityImages: newImages });
  };

  const handleThreeColChange = (i, field, value) => {
    const newCols = [...homeData.threeColSection];
    newCols[i][field] = value;
    setHomeData({ ...homeData, threeColSection: newCols });
  };

  const handleTestimonialChange = (e, index) => {
    const newVideos = [...homeData.testimonialVideos];
    newVideos[index] = e.target.value;
    setHomeData({ ...homeData, testimonialVideos: newVideos });
  };

  const addBannerVideo = () =>
    setHomeData({ ...homeData, bannerVideos: [...homeData.bannerVideos, ""] });

  const addActivityImage = () =>
    setHomeData({
      ...homeData,
      activityImages: [...homeData.activityImages, ""],
    });

  const addTestimonialVideo = () =>
    setHomeData({
      ...homeData,
      testimonialVideos: [...homeData.testimonialVideos, ""],
    });

  const handleSave = async () => {
    try {
      await axios.put("http://localhost:5000/api/home", homeData);
      toast.success("Home page updated successfully!");
    } catch (error) {
      toast.error("Error saving data!");
      console.error(error);
    }
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div className="admin-container">
      <Toaster position="top-right" />
      <h2 className="admin-title">🏠 Manage Home Page</h2>

      {/* === Banner Video Section === */}
      <section className="admin-card">
        <h3 className="admin-section-title">🎥 Banner Videos</h3>
        {homeData.bannerVideos.map((video, i) => (
          <input
            key={i}
            type="text"
            value={video}
            onChange={(e) => handleVideoChange(e, i)}
            placeholder={`Video URL ${i + 1}`}
            className="input-url"
          />
        ))}
        <button className="add-btn" onClick={addBannerVideo}>
          + Add Banner Video
        </button>
      </section>

      {/* === Welcome & Activities Section === */}
      <section className="admin-card two-col-admin">
        <div className="left">
          <h3 className="admin-section-title">👋 Welcome Text</h3>
          <ReactQuill
            theme="snow"
            value={homeData.welcomeText}
            onChange={(value) =>
              setHomeData({ ...homeData, welcomeText: value })
            }
            placeholder="Write the welcome message shown on the homepage..."
          />
        </div>

        <div className="right">
          <h3 className="admin-section-title">🖼️ Activities Images</h3>
          {homeData.activityImages.map((img, i) => (
            <input
              key={i}
              type="text"
              value={img}
              onChange={(e) => handleActivityImageChange(e, i)}
              placeholder={`Image URL ${i + 1}`}
              className="input-url"
            />
          ))}
          <button className="add-btn" onClick={addActivityImage}>
            + Add Activity Image
          </button>
        </div>
      </section>

      {/* === Three Column Section === */}
      <section className="admin-card">
        <h3 className="admin-section-title">📊 Three Column Section</h3>
        <div className="three-col-admin">
          {homeData.threeColSection.map((col, i) => (
            <div key={i} className="col-card">
              <input
                type="text"
                value={col.title}
                onChange={(e) => handleThreeColChange(i, "title", e.target.value)}
                placeholder="Column Title"
                className="input-url"
              />
              <ReactQuill
                theme="snow"
                value={col.content}
                onChange={(val) => handleThreeColChange(i, "content", val)}
                placeholder="Column Content..."
              />
              <input
                type="text"
                value={col.image}
                onChange={(e) =>
                  handleThreeColChange(i, "image", e.target.value)
                }
                placeholder="Image or Video URL"
                className="input-url"
              />
            </div>
          ))}
        </div>
      </section>

      {/* === Testimonials Section === */}
      <section className="admin-card">
        <h3 className="admin-section-title">🎬 Testimonial Videos</h3>
        {homeData.testimonialVideos.map((video, i) => (
          <input
            key={i}
            type="text"
            value={video}
            onChange={(e) => handleTestimonialChange(e, i)}
            placeholder={`Testimonial Video URL ${i + 1}`}
            className="input-url"
          />
        ))}
        <button className="add-btn" onClick={addTestimonialVideo}>
          + Add Testimonial Video
        </button>
      </section>

      <button className="admin-save-btn" onClick={handleSave}>
        💾 Save All Changes
      </button>
    </div>
  );
}
